proved Unarmed Strike","Maximize Spell","Power Attack","Quicken Spell","Reach Spell","Sacred Spell","Still Spell","Stunning Fist"],"printedDwarfTraits":{"attackBonusVsOrcsAndGoblinoids":1,"willSaveBonusVsSpellsAndSpellLikeAbilities":2,"fortitudeSaveBonusVsPoison":2,"dodgeBonusVsGiants":4,"darkvision":true,"stonecunning":{"bonus":2,"distanceFeet":10,"canFindStoneworkTrapsAsRogue":true,"intuitDepth":true},"appraiseBonusStoneMetal":2,"craftProfessionBonusStoneMetal":2},"salientDivineAbilities":["Alter Reality","Area Divine Shield","Clearsight","Command Plants","Divine Blessing (Constitution)","Divine Earth Mastery","Divine Fast Healing","Divine Inspiration (hope)","Divine Shield","Extra Domain (Chaos)","Extra Domain (Liberation)","Gift of Life"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"earth":{"turnOrDestroyAirCreaturesPerDay":10,"rebukeOrCommandEarthCreaturesPerDay":10},"goodSpellsCasterLevelBonus":1,"liberation":{"moraleBonusOnSavesAgainstEnchantments":2},"plant":{"rebukeOrCommandPlantCreaturesPerDay":10}},"spellLikeAbilities":{"casterLevel":20,"chaosGoodCasterLevel":21,"saveDc":"26 + spell level","printedList":["aid","animate objects","barkskin","blade barrier","break enchantment","changestaff","chaos hammer","cloak of chaos","command plants","control plants","dispel evil","dispel law","earthquake","elemental swarm (earth only)","entangle","freedom of movement","greater dispelling","holy aura","holy smite","holy word","iron body","magic circle against evil","magic circle against law","magic stone","mind blank","plant growth","protection from evil","protection from law","refuge","remove curse","remove fear","remove paralysis","repel wood","shambler","shatter","soften earth and stone","spike stones","stone shape","stoneskin","summon monster IX (chaos or good only)","unbinding","wall of stone","wall of thorns","word of chaos"]},"spellcasting":{"clericSpellsPerDay":"6/9/8/8/8/8/6/6/6/6","clericBaseDc":"19 + spell level"},"lesserDeityTraits":{"mayTake10OnChecks":true,"natural1NotAutomaticFailureOnAttacksOrSaves":true,"immortal":true},"senses":{"normalRangeMiles":10,"visionIncludesDarkvision":true,"remoteSenseAnchors":["worshipers","holy sites","objects","locations where a title or name was spoken in the last hour"],"maximumRemoteLocations":5,"sensingBlockLocations":2,"sensingBlockHours":10},"portfolioSense":"Senses the suffering of any group of five hundred or more people.","automaticActions":{"skills":["Animal Empathy","Craft (metalworking)","Craft (stoneworking)","Diplomacy","Gather Information","Sense Motive"],"freeActionDcMaximum":20,"maximumPerRound":5},"createMagicItems":"Can create magic items involving earth, dwarves, protection, or endurance, up to 30,000 gp.","avatarStatus":"Dennari does not possess the Avatar salient divine ability; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["Chaotic","Good"],"damageReduction":"20/epic","fireResistance":15,"additionalOutsiderSkillPoints":45,"additionalFeat":1,"classChanges":{"cleric":"No class-feature change in the official revision."},"ancestry":"Use revised dwarf racial traits in 3.5 execution while preserving the printed 3.0 dwarf-trait block above.","skills":{"defunct":{"Animal Empathy":"Replace ranks with an equal number of ranks in another skill; revised creatures commonly use Handle Animal and wild empathy where class features grant it."},"legacyNavigation":"Intuit Direction is a 3.0 skill; resolve navigation through the revised Survival skill when rebuilding the stat block."},"feats":{"extraOutsiderFeat":1,"additionalFeatSelection":"Choose an appropriate revised or epic feat; the official update grants one but does not mandate a specific selection."},"spellUpdates":["Use revised spell names and effects for all domain spell-like abilities.","greater dispelling -> greater dispel magic"],"divineAbilities":"Use the official revised salient-divine-ability text where an ability changed."}}}')
